INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18771$nota-0256$m18771$, $m18772$Exercise Physiology McArdle.pdf$m18772$, $m18773$629$m18773$, $m18774$A fluid loss equivalent to only 1% of body mass increases rectal temperature compared with the same exercise and normal hydration. For each liter of sweat-loss dehydration, exercise heart rate increases 8 b·min−1, with a corresponding 1.0 L·min−1 decrease in cardiac output.$m18774$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m18775$nota-0256$m18775$, $m18776$nota-0182$m18776$, $m18777$complementa$m18777$, $m18778$nota-0182 descreve o mecanismo qualitativo da deriva cardíaca (desidratação como um dos fatores); esta nota quantifica especificamente o efeito da desidratação por suor sobre FC e débito cardíaco, útil para separar a contribuição da desidratação de outras causas de decoupling$m18778$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m18779$nota-0256$m18779$, $m18780$nota-0239$m18780$, $m18781$complementa$m18781$, $m18782$nota-0239 quantifica deriva cardíaca em ambiente termoneutro sem desidratação relevante; esta nota quantifica especificamente o efeito de desidratação/calor, mecanismo complementar de subida de FC ao longo do treino$m18782$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18783$nota-0257$m18783$, $m18784$Exercise Physiology McArdle.pdf$m18784$, $m18785$630$m18785$, $m18786$In terms of performance, dehydration equal to 4.3% of body mass reduced walking endurance by 48%; concurrently, VO2max decreased by 22%. These same experiments showed decreased endurance performance (−22%) and VO2max (−10%) when dehydration averaged only 1.9% of body mass.$m18786$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18787$nota-0257$m18787$, $m18788$Exercise Physiology McArdle.pdf$m18788$, $m18789$628$m18789$, $m18790$Even a modest fluid loss of 2% body mass adversely affects exercise performance.$m18790$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m18791$nota-0257$m18791$, $m18792$nota-0227$m18792$, $m18793$complementa$m18793$, $m18794$nota-0227 descreve como monitorar a taxa de desidratação por variação de peso corporal; esta nota quantifica o impacto no desempenho de diferentes níveis de desidratação medidos da mesma forma$m18794$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18795$nota-0268$m18795$, $m18796$Exercise Physiology McArdle.pdf$m18796$, $m18797$639$m18797$, $m18798$Humans possess much less capacity for adaptation to long-term cold exposure than to prolonged heat exposure. The basic response of Eskimos and Lapps involves avoiding the cold or minimizing its effects. Their clothing provides a near-tropical microclimate; the temperature inside an igloo typically averages 15.6°C (60°F) despite freezing outside temperatures.$m18798$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18799$nota-0268$m18799$, $m18800$Exercise Physiology McArdle.pdf$m18800$, $m18801$640$m18801$, $m18802$The following three responses give some indication of a mild acclimatization to chronic cold exposure: 1. Shivering occurs at a lower body temperature because more heat is generated without shivering. 2. Improved ability to sleep in the cold. 3. Change in peripheral blood flow distribution that either conserves heat in the core or warms the extremities to prevent cold injury.$m18802$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m18803$nota-0268$m18803$, $m18804$nota-0254$m18804$, $m18805$complementa$m18805$, $m18806$contraste direto: a aclimatização ao calor (nota-0254) é rápida, robusta e bem documentada (10-14 dias, ganhos grandes); a aclimatização ao frio é lenta, fraca e majoritariamente comportamental — assimetria fisiológica importante$m18806$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18807$nota-0269$m18807$, $m18808$Exercise Physiology McArdle.pdf$m18808$, $m18809$618$m18809$, $m18810$Shivering generates metabolic heat, but physical activity provides the greatest contribution in defending against cold. Energy metabolism during movement sustains a constant core temperature in air as cold as −30°C (−22°F) without reliance on a heavy, restrictive clothing barrier. Internal temperature, not the body's heat production per se, mediates the thermoregulatory response to cold.$m18810$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18811$nota-0269$m18811$, $m18812$Exercise Physiology McArdle.pdf$m18812$, $m18813$617$m18813$, $m18814$the drive to maintain thermal balance remains so strong that it readily triggers... an oxygen consumption of 1200 mL·min−1 from shivering in severe cold.$m18814$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m18815$nota-0269$m18815$, $m18816$nota-0268$m18816$, $m18817$complementa$m18817$, $m18818$esta nota detalha o mecanismo pelo qual o exercício (não a aclimatização) é a principal defesa eficaz contra o frio durante atividade física$m18818$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18819$nota-0277$m18819$, $m18820$Exercise Physiology McArdle.pdf$m18820$, $m18821$693$m18821$, $m18822$NASA's greatest biomedical concern involves the 1% per month loss in weight-bearing bone mass during space missions... Bone mineral density (BMD) declined at all seven sites measured, with spine, neck of femur, trochanter, and pelvis decreasing more than 1% per month.$m18822$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18823$nota-0277$m18823$, $m18824$Exercise Physiology McArdle.pdf$m18824$, $m18825$693$m18825$, $m18826$Under normal gravity conditions, the small intestine absorbs approximately 250 to 500 mg of calcium for every 1000 mg consumed... With increased gravitational loading, calcium absorption by bone increases to spare overall calcium loss. In a microgravity environment, reduced calcium intestinal absorption exacerbates calcium fecal loss... Abnormal calcium excretion from bone resorption disrupts calcium homeostasis, which in turn decreases total body calcium and bone mass.$m18826$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18827$nota-0277$m18827$, $m18828$Exercise Physiology McArdle.pdf$m18828$, $m18829$694$m18829$, $m18830$Onboard, multimode exercise training and lower-limb exercise has not prevented BMD loss, despite United States and Soviet crewmembers' commitment to intense resistance-type daily workout regimens.$m18830$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m18831$nota-0277$m18831$, $m18832$nota-0134$m18832$, $m18833$complementa$m18833$, $m18834$outro dado de fisiologia ambiental (fora do escopo calor/frio) presente neste mesmo grupo de capítulos do McArdle, mecanismo de resposta óssea à carga gravitacional/mecânica$m18834$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m18835$nota-0284$m18835$, $m18836$Exercise Physiology McArdle.pdf$m18836$, $m18837$773$m18837$, $m18838$For nine professional cyclists who participated in the Giro d'Italia 3-wk stage race in Italy, markers of bone activity measured 1 day prerace, and 12 and 22 days during the race indicated resorption of bone brought on by the race.$m18838$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m18839$nota-0284$m18839$, $m18840$nota-0277$m18840$, $m18841$complementa$m18841$, $m18842$nota-0277 estabelece o mecanismo geral (carga mecânica insuficiente → menor estímulo osteogênico) via analogia com microgravidade; esta nota traz dado direto e específico de ciclistas profissionais em prova real, reforçando a mesma conclusão sem depender de extrapolação$m18842$)
